          "explanation": "Piggyback: tap into the users of another platform, as PayPal did on eBay, YouTube on Myspace and Justdial with yellow-pages listings. The other options define follow-the-rabbit, seeding and marquee. The official mock uses the same option set to ask about follow-the-rabbit.",
          "source": "Lecture 4, '8 strategies to deal with the chicken-or-egg dilemma'; Parker et al. (2016), ch. 5",
