          "num": 33,
          "qid": "L1-08",
          "stem": "Parker et al. (2016) argue that platforms 'invert the firm'. How many of the following shifts are consistent with this idea?\n• Marketing moves from broadcasting to segmentation, virality and social influence\n• Strategy moves from orchestrating external resources to controlling unique internal resources\n• Innovation moves from in-house R&D labs to crowdsourcing and open innovation\n• Human resource management moves from managing crowds to managing employees",
          "options": [
            {
              "l": "a",
              "t": "2 of the items"
            },
            {
              "l": "b",
              "t": "3 of the items"
            },
            {
              "l": "c",
              "t": "Only 1 of the items"
            },
            {
              "l": "d",
              "t": "All of the items"
            }
          ],
          "correct": [
            "a"
          ],
          "note": "",
          "topic": "t_lecture1",
          "kind": "concept",
          "fmt": "howmany",
          "explanation": "Two are correct (marketing and innovation). Inversion means the focus shifts from inside to outside the firm. The strategy and HR statements are reversed: strategy moves from controlling internal resources to orchestrating external ones, and HR moves from employees to crowds.",
          "source": "Lecture 1, 'Platforms invert the firm'; Parker et al. (2016), ch. 1-2"
