          "explanation": "Stars attract other producers and consumers: malls give Target attractive leases, Skillshare and Indiegogo court celebrity creators, and EA got special terms for the Xbox. The lecture links this to the marquee strategy. Subsidizing one side (the 'ladies night' model) applies to a whole side of the market, not to a few superusers.",
