          "kind": "situational",
          "fmt": "single",
          "explanation": "Lecture 1 contrasts the editorial pipeline in publishing with Amazon's self-publishing platform: gatekeepers (editors) are replaced by signals, such as feedback, provided by the community of readers, so the platform grows to scale faster. Unlocking new supply refers to spare capacity (Airbnb rooms), and supply economies of scale belong to industrial-era pipelines.",
          "source": "Lecture 1, 'Advantages of platforms'; Parker et al. (2016), ch. 1"
