          "note": "",
          "explanation": "Proprietary: one firm manages and sponsors (Apple). Licensing: one sponsor, many managers (Google licenses Android to device makers). Shared: many sponsors and many managers (Linux). The joint venture model, with many sponsors and one manager, is Orbitz, sponsored by several airlines.",
          "source": "Parker et al. (2016), ch. 7, 'Manager and sponsor participation'"
