          "explanation": "Big-bang adoption uses traditional push tactics to trigger simultaneous on-boarding. Twitter's usage tripled during SXSW, from 20,000 to 60,000 tweets a day. Lecture 4 adds Foursquare (SXSW 2009) and the quick-commerce apps (Getir, Flink, Gorillas, Zapp) advertising on Amsterdam trams.",
          "source": "Lecture 4, 'Big bang adoption'; Parker et al. (2016), ch. 5"
