          "explanation": "Sender: the user sharing her creation. Value unit: the poster. External network: Instagram, where the value unit spreads. Recipient: the friend who signs up and may become a sender. For Instagram itself, Facebook played the role of the external network.",
          "source": "Lecture 4, 'Other strategies: viral growth'; Parker et al. (2016), ch. 5"
