          "note": "",
          "explanation": "'Network effects are not everything.' Many low-quality meetups created noise, a negative network effect. The fee filtered out organizers who weren't serious and built a culture of quality. Zvents shows the other side of the coin: lots of visitors but too little control to capture the value.",
          "source": "Lecture 4, 'Network effects are not everything'; Parker et al. (2016), ch. 6"
