          "note": "",
          "explanation": "'Users first, monetization later' (Haier's version: 'You never take first money'). Lecture 4 adds: avoid charging for value that used to be free, avoid reducing access to value users are used to, and create new additional value instead. Myspace's rush to monetize under News Corp is Parker et al.'s cautionary tale.",
